o:[{hi:'हाइड्रॉलिक लिफ्ट',en:'Hydraulic lift'},{hi:'हवाई जहाज़',en:'Airplane'},{hi:'रॉकेट',en:'Rocket'},{hi:'थर्मामीटर',en:'Thermometer'}],a:0,
e:{hi:'हाइड्रॉलिक लिफ्ट व ब्रेक में — बंद द्रव में एक बिंदु पर लगाया दाब सब दिशाओं में समान रूप से बँट जाता है। छोटे पिस्टन का हल्का बल बड़े पिस्टन पर भारी बोझ उठा लेता है।',en:'Hydraulic lift/brakes — pressure transmits equally in a confined fluid.'},
