o:[{hi:'गोले के द्रव्यमान पर',en:'Mass of the bob'},{hi:'डोरी की लंबाई पर',en:'Length of the string'},{hi:'झूलने के आयाम पर',en:'Amplitude of swing'},{hi:'गोले के रंग पर',en:'Colour of the bob'}],a:1,
e:{hi:'केवल लंबाई पर (T = 2π√(l/g)) — लंबा लोलक धीरे झूलता है। द्रव्यमान बदलने से आवर्तकाल नहीं बदलता, इसलिए घड़ी का पेंडुलम एक समान समय देता है।',en:'Only on length (T = 2π√(l/g)); mass does not matter.'},
