o:[{hi:'3.6×10³ जूल',en:'3.6×10³ J'},{hi:'3.6×10⁶ जूल',en:'3.6×10⁶ J'},{hi:'4.2 जूल',en:'4.2 J'},{hi:'746 जूल',en:'746 J'}],a:1,
