o:[{hi:'3×10⁶ m/s',en:'3×10⁶ m/s'},{hi:'3×10⁸ m/s',en:'3×10⁸ m/s'},{hi:'3×10⁵ m/s',en:'3×10⁵ m/s'},{hi:'3×10¹⁰ m/s',en:'3×10¹⁰ m/s'}],a:1,
