o:[{hi:'उपग्रह',en:'A satellite'},{hi:'ह्यूमनॉइड रोबोट',en:'A humanoid robot'},{hi:'रॉकेट',en:'A rocket'},{hi:'दूरबीन',en:'A telescope'}],a:1,
